 private Dialog dialog;private LinearLayout messages;private ScrollView scroll;private EditText input;private Button send;private TextView status,context;private FrameLayout viewport;private LinearLayout sheet,quickActions;private TextView disclosure;private int imeBottom=0,systemTop=0,systemBottom=0,systemLeft=0,systemRight=0;private boolean keyboardVisible=false;private JSONArray history;private boolean busy=false,retryWarning=false;
